from taf.fdsw.rc.interfaces.FDSW23B.fdsw import FDSW23B
from taf.fdsw.rc.interfaces.FDSW23C.autoconnection import AutoConfiguration23C
from taf.fdsw.rc.interfaces.FDSW23C.time import Time


class FDSW23C(FDSW23B):
    VERSION_NAME = 'FDSW23C'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW23C, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)
        self.autoconnection = AutoConfiguration23C(client=self._client)
        self.time = Time(client=self._client)
